const items=[{id:'wood',name:'敲木鱼',en:'A LITTLE PEACE',desc:'笃，笃，笃。让念头歇一会儿。',tag:'无限循环 · 不必动手',bg:'#e9e0ce',note:'木鱼会自己一直敲。也可以点击木鱼，添一声笃。',label:'一声一声，心事就轻了。'}, {id:'frog',name:'听蛙叫',en:'BY THE QUIET POND',desc:'池塘不说话，青蛙偶尔说两句。',tag:'一方池塘 · 慢慢等',bg:'#dfe7d5',note:'一小时内，会有一两只青蛙路过。点击青蛙，可以打个招呼。',label:'今天，池塘也没什么大事。'},{id:'incense',name:'等一炷香',en:'LET IT DRIFT AWAY',desc:'看一缕烟，走它自己的路。',tag:'约 30 分钟 · 一炷香的时间',bg:'#e7e4dd',note:'一炷香需要约 30 分钟燃尽。离开再回来，它也会继续燃烧。',label:'让时间，变成一缕烟。'},{id:'snail',name:'陪蜗牛散步',en:'AT ITS OWN PACE',desc:'它有自己的速度，你也可以有。',tag:'偶尔停一停 · 可以戳戳它',bg:'#e4e5d9',note:'点击蜗牛，它会躲进壳里，过 1–2 分钟再出来。停下来时，也许会动动触角。',label:'不用催，我们慢慢来。'},{id:'ants',name:'看蚂蚁搬家',en:'SMALL BUT TOGETHER',desc:'一点点食物，一场小小的大工程。',tag:'投喂互动 · 小小协作现场',bg:'#d5c2a4',note:'没找到食物的蚂蚁，会在 10–15 分钟后回巢休息 3–5 分钟。',label:'忙忙碌碌，也是一种无聊。'}];
function ellipse(c,x,y,rx,ry,color,rot=0){c.beginPath();c.ellipse(x,y,Math.max(.01,rx),Math.max(.01,ry),rot,0,TAU);c.fillStyle=color;c.fill()}
function line(c,points,color,width=1){c.beginPath();c.moveTo(...points[0]);points.slice(1).forEach(p=>c.lineTo(...p));c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.stroke()}
function grad(c,x,y,r,colors){const g=c.createRadialGradient(x-r*.3,y-r*.4,r*.02,x,y,r);colors.forEach((v,i)=>g.addColorStop(i/(colors.length-1),v));return g}
function shadow(c,x,y,rx,ry,a=.12){c.save();c.filter='blur(9px)';ellipse(c,x,y,rx,ry,`rgba(48,43,24,${a})`);c.restore()}
function grain(c,w,h,seed=13){let n=seed;const rnd=()=>{n=(n*16807)%2147483647;return n/2147483647};c.save();for(let i=0;i<1900;i++){const x=rnd()*w,y=rnd()*h;c.fillStyle=rnd()>.4?'#ffffff18':'#51472b13';c.fillRect(x,y,rnd()*2+.4,rnd()*1.3+.4)}c.restore()}
function wood(c,w,h,t,small=false){c.fillStyle='#e9e1d2';c.fillRect(0,0,w,h);const x=w*.49,y=h*.59,s=Math.min(w/420,h/270);c.save();c.translate(x,y);c.scale(s,s);shadow(c,0,62,112,14,.19);ellipse(c,0,55,102,26,'#82704e');ellipse(c,0,49,102,28,grad(c,0,49,110,['#d3b68a','#99805a','#665034']));ellipse(c,0,3,94,64,grad(c,0,3,110,['#be8951','#936037','#5f3c23']));ellipse(c,-27,-17,46,25,'#d2a36a28',-.3);for(let i=0;i<10;i++){c.beginPath();c.ellipse(-2,5,85-i*6,52-i*3,-.13,.16,2.85);c.strokeStyle=i%2?'#ebc89125':'#583d2925';c.lineWidth=1.2;c.stroke()}c.beginPath();c.moveTo(-81,14);c.bezierCurveTo(-25,29,41,8,86,-1);c.lineTo(88,9);c.bezierCurveTo(25,27,-24,38,-82,23);c.fillStyle='#352b21';c.fill();c.beginPath();c.moveTo(-79,14);c.bezierCurveTo(-10,28,48,7,84,-2);c.strokeStyle='#e1b477';c.lineWidth=2;c.stroke();ellipse(c,-77,16,11,13,'#543820',-.2);const phase=(t%2.4)/2.4,strike=Math.pow(Math.max(0,Math.sin(phase*TAU)),12);let swing=-.12;if(phase<.15)swing=-.12-.18*Math.sin(phase/.15*Math.PI/2);else if(phase<.25){const u=(phase-.15)/.10;swing=-.30+.40*(u*u*(3-2*u))}else if(phase<.34){const u=(phase-.25)/.09;swing=.10-.22*(u*u*(3-2*u));}c.save();c.translate(110,-98);c.rotate(swing);line(c,[[0,0],[-77,42]],'#795b37',11);line(c,[[-2,-2],[-76,40]],'#c8a36c',5);ellipse(c,-85,46,24,20,grad(c,-85,46,28,['#d9ba83','#b38c54','#82613c']),-.4);c.restore();if(small){c.font='11px serif';c.fillStyle='#8d7754';c.fillText('笃。',115,-48)}c.restore();grain(c,w,h)}
function frogBody(c,x,y,s,t){c.save();c.translate(x,y);c.scale(s,s);shadow(c,0,27,42,7,.18);ellipse(c,-33,18,22,13,'#687b39',-.4);ellipse(c,33,18,22,13,'#687b39',.4);ellipse(c,0,5,37,30,grad(c,0,3,42,['#c0cc73','#93a64a','#5e7634']));ellipse(c,0,18,24,14,'#bfca83');const puff=1+Math.pow((Math.sin(t*1.4)+1)/2,12)*.4;ellipse(c,0,20,15*puff,9*puff,'#d9dba0');ellipse(c,-20,-18,14,15,'#9bae55');ellipse(c,20,-18,14,15,'#9bae55');for(const ex of [-20,20]){ellipse(c,ex,-20,8,9,'#e1cc77');ellipse(c,ex,-20,4.5,7,'#282c1d');ellipse(c,ex-2,-23,2,2,'#ffffffbc')}c.beginPath();c.moveTo(-15,4);c.quadraticCurveTo(0,12,15,4);c.strokeStyle='#4e622d';c.lineWidth=1.3;c.stroke();for(let i=0;i<12;i++){const a=i*2.4;ellipse(c,Math.cos(a)*27,Math.sin(a)*17+3,2.8,1.6,'#5d77363a')}line(c,[[-18,20],[-27,32],[-39,32]],'#7a9043',4);line(c,[[18,20],[27,32],[39,32]],'#7a9043',4);c.restore()}
function frog(c,w,h,t,visitors=[]){const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,'#dce6d2');g.addColorStop(1,'#9eaf8d');c.fillStyle=g;c.fillRect(0,0,w,h);for(let i=0;i<8;i++){const x=w*(.1+(i*.173)%1),y=h*(.2+(i*.213)% .7);c.strokeStyle='#f5f5da42';c.lineWidth=1;c.beginPath();c.ellipse(x,y,34+Math.sin(t*.6+i)*7,7,0,0,TAU);c.stroke()}const x=w*.5,y=h*.56,s=Math.min(w/400,h/270);shadow(c,x,y+37*s,80*s,14*s);c.save();c.translate(x,y+24*s);c.scale(s,s);c.beginPath();c.ellipse(0,0,83,29,-.15,.28,TAU-.08);c.lineTo(12,-5);c.closePath();c.fillStyle=grad(c,0,0,90,['#9db66d','#748f4f','#5b7b45']);c.fill();for(let i=0;i<7;i++)line(c,[[7,-3],[Math.cos(i*.8)*73,Math.sin(i*.8)*23]],'#d2dd952c',1);c.restore();frogBody(c,x,y-3*s,s*.87,t);for(const v of visitors) frogBody(c,v.x*w,v.y*h,s*.58,t);for(let i=0;i<3;i++){const xx=w*(.05+i*.065);line(c,[[xx,h],[xx+9,h*.60-i*14]],'#6f8056',3*s);ellipse(c,xx+8,h*.63-i*14,4*s,20*s,'#8b7650',.13)}grain(c,w,h)}
function incense(c,w,h,t,progress){const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,'#e9e7e0');g.addColorStop(1,'#d8d8cf');c.fillStyle=g;c.fillRect(0,0,w,h);const x=w*.5,y=h*.81,s=Math.min(w/420,h/300);shadow(c,x,y+15*s,75*s,9*s,.16);ellipse(c,x,y+8*s,65*s,14*s,'#827961');ellipse(c,x,y,67*s,16*s,grad(c,x,y,78*s,['#b9ad8c','#93866a','#70644e']));ellipse(c,x,y-4*s,51*s,10*s,'#c6baa0');for(let i=0;i<28;i++)ellipse(c,x+Math.sin(i*4)*44*s,y-4*s+Math.cos(i*7)*5*s,1.2*s,.6*s,'#82755b50');const top=y-(135*(1-progress)+13)*s;line(c,[[x,y-4*s],[x,top]],'#7c6044',3*s);line(c,[[x-.5*s,y-5*s],[x-.5*s,top]],'#af8d60',1*s);if(progress<1){ellipse(c,x,top,2*s,3*s,'#df8153');c.save();c.globalCompositeOperation='screen';ellipse(c,x,top,4*s,4*s,'#de702a35');c.restore();for(let j=0;j<6;j++){c.beginPath();for(let i=0;i<85;i++){const q=i/84,yy=top-q*(160+12*j)*s,xx=x+(Math.sin(q*8-t*.55+j*.25)*q*22+Math.sin(q*19-t*.8)*q*5)*s;if(!i)c.moveTo(xx,yy);else c.lineTo(xx,yy)}c.strokeStyle=`rgba(255,255,250,${.13-j*.014})`;c.lineWidth=(2+j*1.7)*s;c.filter=`blur(${1+j*.5}px)`;c.stroke()}c.filter='none'}grain(c,w,h)}
function snailBody(c,x,y,s,t,retract=0){c.save();c.translate(x,y);c.scale(s,s);shadow(c,-5,25,56,5,.17);c.save();c.translate(-34*retract,0);c.scale(1-.56*retract,1-.3*retract);c.beginPath();c.moveTo(-63,21);c.bezierCurveTo(-38,9,13,13,38,4);c.bezierCurveTo(45,-1,49,-12,55,-10);c.bezierCurveTo(66,-8,59,10,67,17);c.quadraticCurveTo(23,30,-63,25);c.fillStyle=grad(c,10,14,70,['#b8ae87','#99906e','#747454']);c.fill();for(let i=0;i<27;i++)ellipse(c,-48+i*3.6,22+Math.sin(i*2)*2,.9,.8,'#c6bd963c');const sway=Math.sin(t*1.7)*3,antenna=1-.9*retract;line(c,[[52,-6],[50+sway,-6-28*antenna]],'#8c8e66',2.5);line(c,[[58,-6],[69+sway,-6-23*antenna]],'#8c8e66',2.5);ellipse(c,50+sway,-6-28*antenna,2.3,2.7,'#555c39');ellipse(c,69+sway,-6-23*antenna,2.3,2.7,'#555c39');line(c,[[58,10],[73,3+sway]],'#8c8e66',1.5);c.restore();ellipse(c,-9,-3,35,34,grad(c,-9,-3,42,['#d9b57b','#b48c53','#84633c']),-.13);for(let k=0;k<70;k++){const a=k/70*TAU*2.5,r=30*(1-k/75);const a2=(k+1)/70*TAU*2.5,r2=30*(1-(k+1)/75);line(c,[[-9+Math.cos(a)*r,-3+Math.sin(a)*r],[-9+Math.cos(a2)*r2,-3+Math.sin(a2)*r2]],'#79562f99',2.4)}for(let i=0;i<20;i++){const a=i*.31;line(c,[[-9+Math.cos(a)*31,-3+Math.sin(a)*31],[-9+Math.cos(a+.06)*26,-3+Math.sin(a+.06)*26]],'#f3d4a74d',1)}c.restore()}
function snail(c,w,h,t,state){c.fillStyle='#e0e2d6';c.fillRect(0,0,w,h);for(let i=0;i<5;i++){line(c,[[0,h*(.15+i*.23)],[w,h*(.15+i*.23)+3]],'#c6cbbd55',2);line(c,[[w*(i%2?.22:.67),h*(.15+i*.23)],[w*(i%2?.22:.67),h*(.38+i*.23)]],'#c6cbbd55',2)}const x=state?state.x*w:w*.50,y=h*.58,s=Math.min(w/440,h/270);if(state){line(c,[[Math.max(0,x-130*s),y+23*s],[x-36*s,y+23*s]],'#f8fff34c',2)}snailBody(c,x,y,s,t,state?.retract||0);grain(c,w,h)}
function ant(c,x,y,a,t,s=1,carryingRice=false){c.save();c.translate(x,y);c.rotate(a);c.scale(s,s);for(let i=-1;i<=1;i++){const shift=Math.sin(t*22+i*2)*2;line(c,[[-1+i*3,-1],[i*3-3,-5-shift],[i*3-1,-8]],'#44382b',.8);line(c,[[-1+i*3,1],[i*3-3,5+shift],[i*3-1,8]],'#44382b',.8)}ellipse(c,-5,0,4.6,3.1,'#403326');ellipse(c,1,0,2.9,1.9,'#53402c');ellipse(c,5,0,2.6,2.3,'#3c3226');line(c,[[6,-1],[10,-4],[12,-3]],'#433828',.7);line(c,[[6,1],[10,4],[12,3]],'#433828',.7);ellipse(c,-6,-1,1.8,.6,'#a28c653d');if(carryingRice){ellipse(c,11,0,7,2.8,'#f4efcf',-.2);ellipse(c,10,-.7,5,1,'#fffcec',-.2)}c.restore()}
function foodDraw(c,f){c.save();c.translate(f.x,f.y);c.rotate(f.rotation||.2);if(f.mode==='entering')c.scale(Math.max(.08,1-(Date.now()-f.enteredAt)/850),Math.max(.08,1-(Date.now()-f.enteredAt)/850));shadow(c,0,4,f.type==='rice'?7:17,3,.12);if(f.type==='rice'){ellipse(c,0,0,7,2.8,'#f4efcf',-.4);ellipse(c,-1,-.7,5,1,'#fffcec',-.4)}else if(f.type==='cookie'){ellipse(c,0,0,18,15,'#987042');ellipse(c,0,-2,18,15,'#d8ac6b');ellipse(c,-3,-6,12,8,'#e9bf7c');for(let j=0;j<9;j++)ellipse(c,Math.sin(j*5)*13,Math.cos(j*7)*10-2,1.4,1,'#9b733d')}else{c.fillStyle='#9e5746';c.fillRect(-19,-12,38,29);c.fillStyle='#d98d78';c.fillRect(-19,-17,38,27);for(let j=0;j<14;j++)ellipse(c,Math.sin(j*5)*16,Math.cos(j*7)*10-4,1.9,1.1,'#f1bea3')}c.restore()}
let dirtCache;
function dirt(c,w,h){if(!dirtCache||dirtCache.width!==w||dirtCache.height!==h){dirtCache=document.createElement('canvas');dirtCache.width=w;dirtCache.height=h;const q=dirtCache.getContext('2d');q.fillStyle='#c7af88';q.fillRect(0,0,w,h);let n=91;const rnd=()=>{n=n*16807%2147483647;return n/2147483647};for(let i=0;i<6500;i++){const x=rnd()*w,y=rnd()*h,r=rnd()*2.3;q.fillStyle=['#e3d0ab88','#8e70494a','#a58b6133'][i%3];q.beginPath();q.ellipse(x,y,r,r*.6,rnd()*TAU,0,TAU);q.fill()}for(let i=0;i<20;i++){const x=rnd()*w,y=rnd()*h;line(q,[[x,y],[x+7,y+3],[x+15,y+2]],'#8f795526',.7)}}c.drawImage(dirtCache,0,0)}
function antsScene(c,w,h,t,state){dirt(c,w,h);const nx=w*.87,ny=h*.26;shadow(c,nx,ny+5,36,21,.16);ellipse(c,nx,ny,35,23,grad(c,nx,ny,40,['#7b613b','#aa8c60','#c7af88']));ellipse(c,nx,ny-2,18,11,'#50422d');ellipse(c,nx,ny-3,13,7,'#372f24');if(state){for(const f of state.foods)if(!(f.type==='rice'&&(f.mode==='carrying'||f.mode==='entering')))foodDraw(c,f);for(const a of state.ants)if(a.mode!=='rest'){const rice=a.food?.type==='rice'&&(a.food.mode==='carrying'||a.food.mode==='entering');ant(c,a.x,a.y,a.angle,t,Math.min(1.1,w/700+.45),rice)}}else{for(let i=0;i<20;i++){const x=w*(.10+(i*.117)% .78),y=h*(.25+(i*.131)% .63);ant(c,x,y,i*2,t,.8)}foodDraw(c,{x:w*.36,y:h*.60,type:'cookie'});foodDraw(c,{x:w*.56,y:h*.76,type:'rice'})}}
