const cv=$('#world'),ctx=cv.getContext('2d');let W=1000,H=520;
function resize(){const r=cv.getBoundingClientRect();if(!r.width)return;const oldW=W,oldH=H;W=r.width;H=r.height;const dpr=Math.min(window.devicePixelRatio||1,2);cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(current==='ants'&&state?.ants){for(const a of state.ants){a.x*=W/oldW;a.y*=H/oldH}for(const f of state.foods){f.x*=W/oldW;f.y*=H/oldH}}}
window.addEventListener('resize',resize);
function initAnts(){return {foodType:null,foods:[],delivered:0,ants:Array.from({length:22},(_,i)=>({x:rand(.15,.85)*W,y:rand(.3,.9)*H,angle:rand(0,TAU),turn:0,speed:rand(13,20),mode:'wander',food:null,searchUntil:Date.now()+rand(600,900)*1000,restUntil:0})),nextId:0}}
function openScene(){const id=location.hash.slice(1),it=items.find(x=>x.id===id);$('#home').hidden=!!it;$('#experience').hidden=!it;current=it?.id||null;window.scrollTo(0,0);if(!it)return;sceneStart=Date.now();lastKnock=-1;$('#scene-name').textContent=it.name;$('#scene-desc').textContent=it.label;$('#scene-label').textContent=it.en;$('#scene-index').textContent=`0${items.indexOf(it)+1} / 05`;$('#scene-note').textContent=it.note;$('#food-tools').hidden=id!=='ants';$('#scene-status').textContent='';updateSoundLabel();resize();if(id==='wood')state={extra:0};if(id==='frog')state={visits:Array.from({length:Math.random()<.5?1:2},()=>({at:rand(20,3500),duration:rand(25,45),y:rand(.35,.8)}))};if(id==='incense'){let start;try{start=Number(localStorage.getItem('wls-incense'));if(!start){start=Date.now();localStorage.setItem('wls-incense',String(start))}}catch{start=Date.now()}state={start};}if(id==='snail')state={x:.36,hidden:false,hiddenUntil:0,hideStart:0,retract:0,emergeStart:0,stopUntil:Date.now()+rand(1,5)*1000,nextStop:Date.now()+rand(8,20)*1000};if(id==='ants'){state=initAnts();document.querySelectorAll('[data-food]').forEach(b=>b.classList.toggle('active',false));$('#food-tip').textContent='选一种食物，再点泥土地面投放';}nextCroak=0;cv.style.cursor=id==='ants'?'crosshair':'pointer'}
window.addEventListener('hashchange',openScene);$('#random').onclick=()=>location.hash=items[Math.floor(Math.random()*items.length)].id;$('#next').onclick=()=>location.hash=items[(items.findIndex(i=>i.id===current)+1)%items.length].id;
$('#about').onclick=()=>$('#about-dialog').showModal();$('.dialog-close').onclick=()=>$('#about-dialog').close();$('#about-dialog').onclick=e=>{if(e.target===$('#about-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
function sound(kind){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;if(kind==='wood'){const g=audio.createGain(),o=audio.createOscillator();o.type='sine';o.frequency.setValueAtTime(640,now);o.frequency.exponentialRampToValueAtTime(320,now+.07);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.3,now+.003);g.gain.exponentialRampToValueAtTime(.0001,now+.32);o.connect(g).connect(audio.destination);o.start();o.stop(now+.35);const n=audio.createOscillator(),ng=audio.createGain();n.frequency.value=1250;ng.gain.setValueAtTime(.06,now);ng.gain.exponentialRampToValueAtTime(.0001,now+.035);n.connect(ng).connect(audio.destination);n.start();n.stop(now+.05)}else if(kind==='frog'){for(let i=0;i<3;i++){const at=now+i*.22,o=audio.createOscillator(),g=audio.createGain(),low=audio.createOscillator(),lg=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(380+i*18,at);o.frequency.exponentialRampToValueAtTime(155,at+.24);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(.34,at+.025);g.gain.setValueAtTime(.28,at+.12);g.gain.exponentialRampToValueAtTime(.0001,at+.3);o.connect(g).connect(audio.destination);o.start(at);o.stop(at+.31);low.type='sine';low.frequency.setValueAtTime(115,at);low.frequency.exponentialRampToValueAtTime(82,at+.28);lg.gain.setValueAtTime(.0001,at);lg.gain.exponentialRampToValueAtTime(.15,at+.04);lg.gain.exponentialRampToValueAtTime(.0001,at+.28);low.connect(lg).connect(audio.destination);low.start(at);low.stop(at+.29)}}}catch{muted=true;$('#sound').textContent='此浏览器暂不支持声音'}}
function updateSoundLabel(){$('#sound').textContent=current==='frog'?(muted?'🔇 开启蛙鸣':'🔊 蛙鸣：开'):`声音：${muted?'关':'开'} ♩`}
$('#sound').onclick=()=>{muted=!muted;$('#sound').setAttribute('aria-pressed',String(!muted));updateSoundLabel();if(!muted){audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();if(current==='wood'||current==='frog')sound(current)}};
function chooseFood(type){state.foodType=type;document.querySelectorAll('[data-food]').forEach(b=>b.classList.toggle('active',b.dataset.food===type));$('#food-tip').textContent=`已选${{rice:'米粒',cookie:'饼干',ham:'火腿块'}[type]}，点击地面投放`}
document.querySelectorAll('[data-food]').forEach(b=>b.onclick=()=>chooseFood(b.dataset.food));
cv.onclick=e=>{if(!current)return;const r=cv.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(current==='wood'){state.extra++;sound('wood');}if(current==='frog'){sound('frog');nextCroak=Date.now()+rand(3000,7000)}if(current==='snail'){const sx=state.x*W,sy=H*.58,s=Math.min(W/440,H/270);if(Math.hypot((x-sx)/s,(y-sy)/s)<76&&!state.hidden){state.hidden=true;state.hideStart=Date.now();state.hiddenUntil=state.hideStart+rand(60,120)*1000;state.emergeStart=0;state.retract=0}}if(current==='incense'&&Date.now()-state.start>=1800000){state.start=Date.now();try{localStorage.setItem('wls-incense',String(state.start))}catch{}}if(current==='ants'){if(!state.foodType){$('#food-tip').textContent='先选一种食物，再点地面哦';return}if(state.foods.length>=8){$('#food-tip').textContent='地上已经很多啦，等它们搬一会儿';return}if(Math.hypot(x-W*.87,y-H*.26)<48){$('#food-tip').textContent='请投在蚁窝外面，留一点散步的距离';return}const type=state.foodType;state.foods.push({id:state.nextId++,type,x:clamp(x,25,W-25),y:clamp(y,28,H-32),need:type==='rice'?1:type==='cookie'?Math.floor(rand(9,12)):Math.floor(rand(16,19)),workers:[],mode:'waiting',rotation:rand(-.5,.5)});$('#food-tip').textContent='放好啦。它们会慢慢发现的。'}};
cv.onkeydown=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();if(current==='wood'){state.extra++;sound('wood')}if(current==='frog')sound('frog');if(current==='snail'&&!state.hidden){state.hidden=true;state.hideStart=Date.now();state.hiddenUntil=state.hideStart+rand(60,120)*1000;state.emergeStart=0;state.retract=0}if(current==='incense'&&Date.now()-state.start>=1800000){state.start=Date.now();try{localStorage.setItem('wls-incense',String(state.start))}catch{}}}};
function moveTo(a,x,y,dt,speed){const dx=x-a.x,dy=y-a.y,d=Math.hypot(dx,dy);a.angle=Math.atan2(dy,dx);if(d<speed*dt+2){a.x=x;a.y=y;return true}a.x+=dx/d*speed*dt;a.y+=dy/d*speed*dt;return false}
function updateAnts(dt,now){
 const st=state,nx=W*.87,ny=H*.26;
 for(const f of st.foods){
  if(f.mode==='waiting'){
   const free=st.ants.filter(a=>a.mode==='wander');
   if(free.length>=f.need){f.workers=free.slice(0,f.need);f.mode='gathering';f.workers.forEach((a,i)=>{a.food=f;a.mode='fetch';a.slot=i})}
  }
  if(f.mode==='gathering'&&f.workers.every(a=>a.mode==='ready'))f.mode='carrying';
  if(f.mode==='carrying'){
   const d=Math.hypot(nx-f.x,ny-f.y),speed=f.type==='rice'?13:f.type==='cookie'?8:5;
   if(d<16){f.mode='entering';f.enteredAt=now}
   else{f.x+=(nx-f.x)/d*speed*dt;f.y+=(ny-f.y)/d*speed*dt;f.workers.forEach((a,i)=>{const ang=i/f.need*TAU,rr=f.type==='rice'?10:26;a.x=f.x+Math.cos(ang)*rr;a.y=f.y+Math.sin(ang)*rr;a.angle=Math.atan2(ny-f.y,nx-f.x)})}
  }
  if(f.mode==='entering'){
   f.workers.forEach((a,i)=>moveTo(a,nx+Math.cos(i/f.need*TAU)*3,ny+Math.sin(i/f.need*TAU)*3,dt,a.speed));
   if(now-f.enteredAt>850){f.mode='done';st.delivered++;f.workers.forEach((a,i)=>{a.food=null;a.mode='wander';a.x=nx-19+Math.cos(i/f.need*TAU)*5;a.y=ny+Math.sin(i/f.need*TAU)*5;a.angle=rand(0,TAU);a.searchUntil=now+rand(600,900)*1000})}
  }
 }
 st.foods=st.foods.filter(f=>f.mode!=='done');
 for(const a of st.ants){
  if(a.mode==='fetch'){const f=a.food,ang=a.slot/f.need*TAU,rr=f.type==='rice'?10:26;if(moveTo(a,f.x+Math.cos(ang)*rr,f.y+Math.sin(ang)*rr,dt,a.speed))a.mode='ready'}
  else if(a.mode==='wander'){if(now>a.searchUntil){a.mode='return';continue}a.turn-=dt;if(a.turn<0){a.angle+=rand(-1.7,1.7);a.turn=rand(.5,2.6)}a.x+=Math.cos(a.angle)*a.speed*dt;a.y+=Math.sin(a.angle)*a.speed*dt;if(a.x<12||a.x>W-12){a.angle=Math.PI-a.angle;a.x=clamp(a.x,12,W-12)}if(a.y<14||a.y>H-14){a.angle=-a.angle;a.y=clamp(a.y,14,H-14)}}
  else if(a.mode==='return'){if(moveTo(a,nx,ny,dt,a.speed)){a.mode='rest';a.restUntil=now+rand(180,300)*1000}}
  else if(a.mode==='rest'&&now>a.restUntil){a.mode='wander';a.searchUntil=now+rand(600,900)*1000;a.angle=rand(0,TAU)}
 }
}
function loop(ts){const dt=Math.min((ts-lastFrame)/1000||.016,.08);lastFrame=ts;const now=Date.now(),t=(now-sceneStart)/1000;if(!current){if(ts-lastPreview>100){previews.forEach(p=>renderers[p.id](p.c,600,390,ts/1000,p.id==='incense'?.15:undefined));hc.clearRect(0,0,430,270);snailBody(hc,210,150,1.55,ts/1000);lastPreview=ts}}else if(!document.hidden){if(current==='wood'){wood(ctx,W,H,t);const cycle=Math.floor(t/2.4),phase=t%2.4;if(phase>=.22&&phase<.29&&cycle!==lastKnock){sound('wood');lastKnock=cycle}$('#scene-status').textContent=`笃 · ${Math.max(0,Math.floor(t/2.4))+state.extra} 声`}if(current==='frog'){let vs=[];for(const v of state.visits){let elapsed=t%3600-v.at;if(elapsed>0&&elapsed<v.duration)vs.push({x:-.1+elapsed/v.duration*1.2,y:v.y})}frog(ctx,W,H,t,vs);if(now>nextCroak){sound('frog');nextCroak=now+rand(4500,13000)}$('#scene-status').textContent='青蛙说：今天不上班。'}if(current==='incense'){const elapsed=(now-state.start)/1000,p=clamp(elapsed/1800,0,1);incense(ctx,W,H,t,p);const left=Math.max(0,1800-Math.floor(elapsed));$('#scene-status').textContent=p>=1?'香已燃尽。点击画面，再点一炷。':`一炷香，还剩 ${Math.floor(left/60)} 分 ${String(left%60).padStart(2,'0')} 秒`}if(current==='snail'){if(state.hidden){state.retract=clamp((now-state.hideStart)/650,0,1);if(now>state.hiddenUntil){state.hidden=false;state.emergeStart=now;state.nextStop=now+rand(8,20)*1000}}else if(state.emergeStart){state.retract=1-clamp((now-state.emergeStart)/700,0,1);if(state.retract===0)state.emergeStart=0}else{if(now>state.nextStop){state.stopUntil=now+rand(1,5)*1000;state.nextStop=state.stopUntil+rand(8,25)*1000}if(now>state.stopUntil){state.x+=dt*.0008;if(state.x>.93)state.x=.09}}snail(ctx,W,H,t,state);$('#scene-status').textContent=state.hidden?'嘘，它想自己待一会儿。':now<state.stopUntil?'停一下。也许在想事情。':'它正在很认真地，慢慢走。'}if(current==='ants'){updateAnts(dt,now);antsScene(ctx,W,H,t,state);const carrying=state.foods.filter(f=>f.mode==='carrying'||f.mode==='entering').length;$('#scene-status').textContent=carrying?`${carrying} 份食物正在回家的路上 · 已搬回 ${state.delivered} 份`:state.delivered?`已搬回 ${state.delivered} 份`:'蚂蚁们正在四处寻找食物。'}}requestAnimationFrame(loop)}
openScene();requestAnimationFrame(loop);
